import { Pool } from "pg";

export interface MemberRow {
  userId: string;
  email: string;
  status: "active" | "suspended";
  mfaEnrolled: boolean;
}

export interface RoleGrant {
  userId: string;
  roleName: string;
  grantedBy: string | null;
  grantedAt: Date;
}

export class DirectoryRepository {
  constructor(private readonly pool: Pool) {}

  async membersOfOrg(orgId: string): Promise<MemberRow[]> {
    const { rows } = await this.pool.query(
      `SELECT u.id AS "userId", u.email, m.status, u.mfa_enrolled AS "mfaEnrolled"
         FROM org_memberships m
         JOIN users u ON u.id = m.user_id
        WHERE m.org_id = $1
        ORDER BY u.email`,
      [orgId],
    );
    return rows;
  }

  async grantsForUsers(orgId: string, userIds: string[]): Promise<RoleGrant[]> {
    if (userIds.length === 0) return [];
    const { rows } = await this.pool.query(
      `SELECT g.user_id AS "userId", r.name AS "roleName", g.granted_by AS "grantedBy",
              g.granted_at AS "grantedAt"
         FROM role_grants g
         JOIN roles r ON r.id = g.role_id
        WHERE g.org_id = $1 AND g.user_id = ANY($2)`,
      [orgId, userIds],
    );
    return rows;
  }

  async lastLoginsForUsers(userIds: string[]): Promise<Map<string, Date>> {
    if (userIds.length === 0) return new Map();
    const { rows } = await this.pool.query(
      `SELECT user_id AS "userId", MAX(created_at) AS "lastLogin"
         FROM login_events
        WHERE user_id = ANY($1) AND outcome = 'success'
        GROUP BY user_id`,
      [userIds],
    );
    return new Map(rows.map((r: { userId: string; lastLogin: Date }) => [r.userId, r.lastLogin]));
  }

  async grantorEmail(userId: string): Promise<string | null> {
    const { rows } = await this.pool.query(`SELECT email FROM users WHERE id = $1`, [userId]);
    return rows[0]?.email ?? null;
  }
}

import { DirectoryRepository, RoleGrant } from "./directoryRepository";

export interface AccessReviewEntry {
  email: string;
  status: string;
  mfaEnrolled: boolean;
  lastLogin: Date | null;
  stale: boolean;
  roles: { role: string; grantedBy: string | null; grantedAt: Date }[];
}

const STALE_AFTER_MS = 90 * 24 * 60 * 60 * 1000;

export class AccessReviewService {
  constructor(
    private readonly repo: DirectoryRepository,
    private readonly now: () => Date = () => new Date(),
  ) {}

  async quarterlyReview(orgId: string): Promise<AccessReviewEntry[]> {
    const members = await this.repo.membersOfOrg(orgId);
    const ids = members.map((m) => m.userId);
    const [grants, logins] = await Promise.all([
      this.repo.grantsForUsers(orgId, ids),
      this.repo.lastLoginsForUsers(ids),
    ]);

    const grantsByUser = new Map<string, RoleGrant[]>();
    for (const g of grants) {
      const list = grantsByUser.get(g.userId) ?? [];
      list.push(g);
      grantsByUser.set(g.userId, list);
    }

    const cutoff = this.now().getTime() - STALE_AFTER_MS;
    const entries: AccessReviewEntry[] = [];
    for (const member of members) {
      const lastLogin = logins.get(member.userId) ?? null;
      const roles = [];
      for (const g of grantsByUser.get(member.userId) ?? []) {
        roles.push({
          role: g.roleName,
          grantedBy: g.grantedBy ? await this.repo.grantorEmail(g.grantedBy) : null,
          grantedAt: g.grantedAt,
        });
      }
      entries.push({
        email: member.email,
        status: member.status,
        mfaEnrolled: member.mfaEnrolled,
        lastLogin,
        stale: lastLogin === null || lastLogin.getTime() < cutoff,
        roles,
      });
    }
    return entries;
  }
}
